using System;using System.IO;using Gravivore.Presentation.AudioVfx;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
namespace Gravivore.Editor.AudioVfx {
public static class Phase6BProductionPackBuilder {
public const string Root="Assets/_Game/Content/Presentation/Phase6B",AudioBankPath=Root+"/Audio/Phase6B_AudioBank.asset",PrefabRoot=Root+"/VFX/Prefabs",ReviewScenePath="Assets/_Game/ArtReview/Scenes/Phase6B_AudioVfxReview.unity";
static readonly (Phase6BVfxCue cue,string file,int cap)[] P={(Phase6BVfxCue.PlayerCharge,"PFX_PlayerCharge.prefab",2),(Phase6BVfxCue.PlayerReleaseFlash,"PFX_PlayerReleaseFlash.prefab",3),(Phase6BVfxCue.GravityLashTravel,"PFX_GravityLashTravel.prefab",3),(Phase6BVfxCue.PlayerImpact,"PFX_PlayerImpact.prefab",4),(Phase6BVfxCue.MechanicalKillBurst,"PFX_MechanicalKillBurst.prefab",3),(Phase6BVfxCue.HostileImpact,"PFX_HostileImpact.prefab",4),(Phase6BVfxCue.BossConeTelegraph,"PFX_BossConeTelegraph.prefab",1),(Phase6BVfxCue.BossLineTelegraph,"PFX_BossLineTelegraph.prefab",1),(Phase6BVfxCue.BossCircleTelegraph,"PFX_BossCircleTelegraph.prefab",1),(Phase6BVfxCue.WeldingSparks,"PFX_WeldingSparks.prefab",2),(Phase6BVfxCue.RepairBeam,"PFX_RepairBeam.prefab",2),(Phase6BVfxCue.ScannerSweep,"PFX_ScannerSweep.prefab",1)};
[MenuItem("Gravivore/Phase 6B/Validate Audio VFX Production Pack")] public static void Validate(){var b=AssetDatabase.LoadAssetAtPath<Phase6BAudioBank>(AudioBankPath);if(b==null)throw new InvalidOperationException("Audio bank missing.");b.ValidateOrThrow();foreach(var e in P){var go=AssetDatabase.LoadAssetAtPath<GameObject>($"{PrefabRoot}/{e.file}");if(go==null)throw new InvalidOperationException($"Missing {e.file}.");var fx=go.GetComponent<Phase6BVfxInstance>();if(fx==null||fx.Cue!=e.cue)throw new InvalidOperationException($"Cue mismatch {e.file}.");fx.ValidateOrThrow();if(go.GetComponentInChildren<Collider>(true)!=null||go.GetComponentInChildren<Rigidbody>(true)!=null||go.GetComponentInChildren<Camera>(true)!=null||go.GetComponentInChildren<Light>(true)!=null)throw new InvalidOperationException($"Forbidden component in {e.file}.");}Debug.Log("PHASE 6B AUDIO / VFX PRODUCTION PACK validated.");}
[MenuItem("Gravivore/Phase 6B/Create or Refresh Isolated Review Scene")] public static void CreateReviewScene(){Validate();Directory.CreateDirectory(Path.GetDirectoryName(ReviewScenePath));for(var i=SceneManager.sceneCount-1;i>=0;i--){var s=SceneManager.GetSceneAt(i);if(!string.IsNullOrEmpty(s.path))continue;if(s.rootCount!=0)throw new InvalidOperationException("Save the nonempty untitled scene first.");EditorSceneManager.CloseScene(s,true);}var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(scene);try{var root=new GameObject("PHASE 6B AUDIO VFX REVIEW — NO GAMEPLAY AUTHORITY");var d=root.AddComponent<Phase6BReviewDriver>();var b=AssetDatabase.LoadAssetAtPath<Phase6BAudioBank>(AudioBankPath);var bindings=new Phase6BVfxPool.Binding[P.Length];for(var i=0;i<P.Length;i++){var e=P[i];var fx=AssetDatabase.LoadAssetAtPath<GameObject>($"{PrefabRoot}/{e.file}").GetComponent<Phase6BVfxInstance>();bindings[i]=new Phase6BVfxPool.Binding(e.cue,fx,e.cap);}d.Configure(b,bindings);var cg=new GameObject("Review Camera",typeof(Camera));cg.transform.SetParent(root.transform,false);var c=cg.GetComponent<Camera>();c.transform.position=new Vector3(0,8.5f,-12);c.transform.LookAt(Vector3.forward*1.8f);c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.035f,.045f,.055f);c.fieldOfView=48;var lg=new GameObject("Review Key Light",typeof(Light));lg.transform.SetParent(root.transform,false);var l=lg.GetComponent<Light>();l.type=LightType.Directional;l.intensity=.85f;l.shadows=LightShadows.None;l.transform.rotation=Quaternion.Euler(50,-30,0);EditorSceneManager.SaveScene(scene,ReviewScenePath);}finally{EditorSceneManager.CloseScene(scene,true);}}
}}
